export function formatSummary(items, format = "text") {
  if (format === "json") {
    return JSON.stringify({ count: items.length, items });
  }
  if (format === "text") {
    return `Count: ${items.length} (${items.join(", ")})`;
  }
  throw new Error(`Unsupported format: ${format}`);
}

