import { formatSummary } from "./format.mjs";

const args = process.argv.slice(2);
let format = "text";
const items = [];
for (let i = 0; i < args.length; i += 1) {
  if (args[i] === "--format") {
    format = args[i + 1] ?? "";
    i += 1;
  } else {
    items.push(args[i]);
  }
}
try {
  console.log(formatSummary(items, format));
} catch (error) {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 1;
}

