import assert from "node:assert/strict";
import test from "node:test";
import { formatSummary } from "../src/format.mjs";

test("formats text and json", () => {
  assert.equal(formatSummary(["a", "b"], "text"), "Count: 2 (a, b)");
  assert.deepEqual(JSON.parse(formatSummary(["a"], "json")), { count: 1, items: ["a"] });
});
